def find_zero(xs):
    def poly_derivative(xs):
        return [i * coeff for i, coeff in enumerate(xs)]

    def newton_raphson(xs, x0, tol=1e-5, max_iter=100):
        x = x0
        for _ in range(max_iter):
            f_x = poly(xs, x)
            f_prime_x = poly_derivative(xs)
            x_new = x - f_x / f_prime_x[-1]
            if abs(x_new - x) < tol:
                return x_new
            x = x_new
        return x

    x0 = -xs[-1] / xs[-2]
    return newton_raphson(xs, x0)

