def is_equal_to_sum_even(n):
    even_numbers = list(range(2, n+1, 2))
    combinations = list(itertools.combinations(even_numbers, 4))
    for combination in combinations:
        if sum(combination) == n:
            return True
    return False

def is_equal_to_sum_even(n):
    def can_be_expressed_as_sum_of_two_even_numbers(x):
        return x % 2 == 0 and x // 2 % 2 == 0

    for i in range(2, n // 4 + 1):
        if can_be_expressed_as_sum_of_two_even_numbers(n - 2 * i) and can_be_expressed_as_sum_of_two_even_numbers(n - 2 * i - 2 * i):
            return True
    return False

def is_equal_to_sum_even(n):
    if n % 2 != 0:
        return False
    for x1 in range(1, n // 2):
        for x2 in range(x1, (n - x1) // 2):
            for x3 in range(x2, (n - x1 - x2) // 2):
                x4 = (n - x1 - x2 - x3) // 2
                if x4 >= x3:
                    return True
    return False

